<script setup lang="ts">import sizes from '~/content/sizes.json';const {ar,c}=useCopy();usePageSeo('دليل المقاسات','Size guide');const selected=ref(0);import {whatsapp} from '~/utils/business'
</script><template><div class="container section" style="padding-top:0"><UiBreadcrumbs :title="c('دليل المقاسات','Size guide')"/><div class="page-intro"><h1>{{c('المقاس المناسب يبدأ بالتفاصيل.','The right size starts with the details.')}}</h1><p>{{c('مقاسات كل تصميم وتوزيعها داخل الصندوق تؤكد عند الاستفسار. الجدول أدناه قائمة مرجعية، وليس قياسات معتمدة.','Sizes and box assortments are confirmed per design on enquiry. The table below is a reference list, not verified measurements.')}}</p></div><div class="size-slider"><div class="mannequin" :style="{transform:'scale('+(0.7+selected*.025)+')'}" aria-hidden="true"><div class="head"/><div class="body"/><div class="legs"/></div><div><label for="age-slider">{{c('استكشف فئات المقاسات','Explore size groups')}}: <strong>{{sizes[selected]?.label[ar?'ar':'en']}}</strong></label><input id="age-slider" v-model.number="selected" type="range" min="0" :max="sizes.length-1"/><p>{{c('الرسم توضيحي فقط. اسألنا عن جدول القياس الخاص بالتصميم.','Illustration only. Ask for the measurement chart for your chosen design.')}}</p></div></div><table class="size-table"><thead><tr><th>{{c('المقاس','Size')}}</th><th>{{c('الطول','Height')}}</th><th>{{c('الصدر','Chest')}}</th><th>{{c('الخصر','Waist')}}</th></tr></thead><tbody><tr v-for="(s,i) in sizes" :key="s.size" :class="{selected:i===selected}"><td>{{s.label[ar?'ar':'en']}}</td><td v-for="key in ['height','chest','waist']" :key="key">{{c('يؤكد مع الفريق','Confirm with team')}}</td></tr></tbody></table><div class="how-grid section"><article v-for="[a,e,at,et] in [['الطول','Height','القياس من أعلى الرأس إلى القدمين أثناء الوقوف.','Measure from the top of the head to the feet while standing.'],['الصدر','Chest','مرر شريط القياس حول أوسع منطقة دون شد.','Measure around the fullest chest without pulling tight.'],['الخصر','Waist','القياس حول الخصر الطبيعي، مع ترك راحة للحركة.','Measure around the natural waist, allowing room to move.']]" :key="e"><h3>{{c(a,e)}}</h3><p>{{c(at,et)}}</p></article></div><UiButton :href="whatsapp()"><UiIcon name="whatsapp"/>{{c('اسألنا عن المقاسات والتعبئة','Ask about sizes and packing')}} </UiButton></div></template>
